import React, {Fragment, useContext, useState } from 'react';
import './Create.css';
import { useHistory } from 'react-router-dom';
import Header from '../Header/Header';
import { FirebaseContext, userContext } from '../../store/FirebaseContext';
import { ref, uploadBytes, getDownloadURL, getStorage,getFireStore } from 'firebase/storage';
import { app, firestore } from '../../firebase/config';
import { addDoc, collection } from 'firebase/firestore';

const Create = () => {
  const { storage } = useContext(FirebaseContext);
  const { user } = useContext(userContext);
  const history = useHistory()
  const [name, setName] = useState('');
  const [category, setCategory] = useState('');
  const [price, setPrice] = useState('');
  const [image, setImage] = useState(null);
  const date = new Date()

  const handleSubmit = () => {
    // Check if image is selected
    if (!image) {
      console.log("Please select an image");
      return;
    }

    // Create a reference for storage
    const storageRef = ref(storage, `/images/${image.name}`);
    console.log(storageRef);

    // Upload the image to Firebase Storage
    uploadBytes(storageRef, image)
      .then((snapshot) => {
        // Get the download URL for the uploaded image
        getDownloadURL(snapshot.ref)
          .then((url) => {
            console.log("Image uploaded successfully: ", url);

            addDoc(collection(firestore,'products'),{
              name,
              category,
              price,
              url,
              userid:user.uid,
              createdAt:date.toDateString()
            })
            history.push('/');
          })
          .catch((error) => {
            console.error("Error getting download URL: ", error);
          });
      })
      .catch((error) => {
        console.error("Error uploading image: ", error);
      });
  };
  return (
    <Fragment>
      <Header />
      <card>
        <div className="centerDiv">
          
            <label htmlFor="fname">Name</label>
            <br />
            <input
              className="input"
              type="text"
              value={name}
              id="fname"
              onChange={(e)=>setName(e.target.value)}
              name="Name"
              defaultValue="John"
            />
            <br />
            <label htmlFor="fname">Category</label>
            <br />
            <input
              className="input"
              type="text"
              value={category}
              id="fname"
              onChange={(e)=>setCategory(e.target.value)}
              name="category"
              defaultValue="John"
            />
            <br />
            <label htmlFor="fname">Price</label>
            <br />
            <input
             className="input" 
             type="number"
             value={price} 
             id="fname" 
             onChange={(e)=>setPrice(e.target.value)}
             name="Price" />
            <br />
          
          <br />
          <img alt="Posts" width="200px" height="200px" src={image ? URL.createObjectURL(image): ''  }></img>
        
            <br />
            <input onChange={(e)=>{ 
              setImage(e.target.files[0])
            }} type="file" />
            <br />
            <button onClick={handleSubmit} className="uploadBtn">upload and Submit</button>
        
        </div>
      </card>
    </Fragment>
  );
};

export default Create;
