import React, { useEffect, useContext, useState } from 'react';
import { getDocs, getFirestore,collection,where,query } from 'firebase/firestore'; // Import getDoc

import './View.css';
import { PostContext } from '../../store/PostContext';
import { FirebaseContext } from '../../store/FirebaseContext';
function View() {
  const [userDetails, setUserDetails] = useState(); // Initialize as null
  const {postDetails} = useContext(PostContext)
  const {firebase} = useContext(FirebaseContext)

    useEffect(() => {
        if (!postDetails) return; // Ensure postDetails exists before running the effect

        const { userid } = postDetails;

        // Initialize Firestore from the firebase context
        const db = getFirestore(firebase); // Use the firebase object from the context

        // Create Firestore query
        const usersCollection = collection(db, 'users');
        const q = query(usersCollection, where('id', '==', userid));

        // Fetch data
        getDocs(q).then((res) => {
            if (!res.empty) {
              // Loop through the query results and set the user details
                res.forEach((doc) => {
                  setUserDetails(doc.data());
                  console.log(userid);
                });
            } else {
              console.log('No user found with the provided userid.');
            }
        }).catch((error) => {
          console.error('Error fetching user details:', error);
        });

    }, [postDetails, firebase]);

  return (
    <div className="viewParentDiv">
      <div className="imageShowDiv">
        <img
          src={postDetails?.url}
          alt=""
        />
      </div>
      <div className="rightSection">
          <div className="productDetails">
            <p>&#x20B9; {postDetails?.price}</p>
            <span>{postDetails?.name}</span>
            <p>{postDetails?.category}</p>
            <span>{postDetails?.createdAt}</span>
          </div>
          {userDetails &&<div className="contactDetails">
            <p>Seller details</p>
            <p>{userDetails?.username}</p>
            <p>{ userDetails?.phone }</p>
            </div>}
      </div>
    </div>
  );
}

export default View;

