import React, { useContext, useEffect, useState } from 'react';
import './Header.css';
import OlxLogo from '../../assets/OlxLogo';
import Search from '../../assets/Search';
import Arrow from '../../assets/Arrow';
import SellButton from '../../assets/SellButton';
import SellButtonPlus from '../../assets/SellButtonPlus';
import { FirebaseContext, userContext } from '../../store/FirebaseContext';
import { useHistory } from 'react-router-dom';

function Header() {
  const { user } = useContext(userContext);
  const { auth } = useContext(FirebaseContext);
  const history = useHistory();
  const [location, setLocation] = useState('Your Location');
  const [showLanguages, setShowLanguages] = useState(false);
  const [selectedLanguage, setSelectedLanguage] = useState('ENGLISH');

  useEffect(() => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(() => {
        setLocation('Current Location');
      });
    }
  }, []);

  const handleLogout = () => {
    auth.signOut().then(() => {
      history.push('/login');
    });
  };

  const toggleLanguages = (e) => {
    e.stopPropagation(); // Prevent event from bubbling up
    setShowLanguages((prev) => !prev);
  };

  const handleLanguageSelect = (language) => {
    setSelectedLanguage(language);
    setShowLanguages(false); // Close the language dropdown after selection
  };

  return (
    <div className="headerParentDiv">
      <div className="headerChildDiv">
        <div className="brandName">
          <OlxLogo />
        </div>
        <div className="placeSearch">
          <Search />
          <input type="text" />
          <Arrow />
        </div>
        <div className="productSearch">
          <div className="input">
            <input type="text" placeholder={`Search in ${location}...`} />
          </div>
          <div className="searchAction">
            <Search color="#ffffff" />
          </div>
        </div>
        <div className="language">
          <span>{selectedLanguage}</span>
          <Arrow onClick={toggleLanguages} />
          {showLanguages && (
            <div className="languageOptions">
              <span onClick={() => handleLanguageSelect('ENGLISH')}>ENGLISH</span>
              <span onClick={() => handleLanguageSelect('HINDI')}>HINDI</span>
            </div>
          )}
        </div>
        <div className="loginPage">
          <a style={{ color: 'black' }} href="/login">
            <span>{user ? `Welcome ${user.displayName}` : 'Login'}</span>
            <hr />
          </a>
        </div>
        {user && <span onClick={handleLogout}>Logout</span>}
        <div className="sellMenu">
          <SellButton />
          <div className="sellMenuContent">
            <SellButtonPlus />
            <span onClick={() => history.push('/create')}>SELL</span>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Header;

